import java.math.BigDecimal
import java.math.RoundingMode

class Ledger {
    private val balances = HashMap<String, BigDecimal>()
    private val log = HashMap<String, MutableList<BigDecimal>>()

    fun openAccount(id: String, initial: BigDecimal = BigDecimal.ZERO) {
        if (balances.containsKey(id)) {
            throw IllegalArgumentException("Account $id already exists")
        }
        // Validate initial amount has at most 2 decimal places
        validateAmount(initial)
        balances[id] = initial.setScale(2, RoundingMode.HALF_UP)
        log[id] = mutableListOf()
    }

    fun balance(id: String): BigDecimal {
        return balances.getValue(id).setScale(2, RoundingMode.HALF_UP)
    }

    fun transfer(from: String, to: String, amount: BigDecimal) {
        // Validate amount
        validateAmount(amount)

        val amountToTransfer = amount.setScale(2, RoundingMode.HALF_UP)

        // Check for sufficient funds before making any changes
        val fromBalance = balances.getValue(from)
        if (fromBalance - amountToTransfer < BigDecimal.ZERO) {
            throw IllegalStateException("insufficient funds")
        }

        // Apply the transfer atomically
        balances[from] = fromBalance - amountToTransfer
        log.getValue(from).add(-amountToTransfer)

        val toBalance = balances.getValue(to)
        balances[to] = toBalance + amountToTransfer
        log.getValue(to).add(amountToTransfer)
    }

    fun history(id: String): List<BigDecimal> = log.getValue(id).map { it.setScale(2, RoundingMode.HALF_UP) }

    companion object {
        fun split(total: BigDecimal, n: Int): List<BigDecimal> {
            if (n <= 0) {
                return emptyList()
            }

            // Validate total amount has at most 2 decimal places
            validateAmount(total)

            val totalScaled = total.setScale(2, RoundingMode.HALF_UP)

            // Calculate base amount per person using division that truncates
            val basePart = totalScaled.divide(BigDecimal(n), 2, RoundingMode.DOWN)

            // Calculate remainder in cents to distribute extra cents
            val totalCents = totalScaled.multiply(BigDecimal(100)).toBigInteger()
            val nBigInteger = BigInteger.valueOf(n.toLong())
            val remainderCents = totalCents % nBigInteger

            val result = mutableListOf<BigDecimal>()

            // Distribute remainder by giving the first 'remainderCents' people one extra cent
            for (i in 0 until n) {
                val extraCents = if (i < remainderCents) 1 else 0
                val partInCents = basePart.multiply(BigDecimal(100)).toBigInteger().toLong() + extraCents
                result.add(BigDecimal(partInCents).divide(BigDecimal(100), 2, RoundingMode.HALF_UP))
            }

            return result
        }

        private fun validateAmount(amount: BigDecimal) {
            if (amount.compareTo(BigDecimal.ZERO) <= 0) {
                throw IllegalArgumentException("Amount must be positive")
            }

            // Check scale is at most 2 (if scale > 2, there are more than 2 decimal places)
            if (amount.scale() > 2) {
                // Also check if it's non-zero beyond 2 decimal places
                val scaledAmount = amount.setScale(2, RoundingMode.DOWN)
                if (scaledAmount != amount) {
                    throw IllegalArgumentException("Amount must have at most 2 decimal places")
                }
            }
        }
    }
}
