```kotlin
import java.util.*

class LruCache<K, V>(val capacity: Int, private val onEvict: (K, V) -> Unit = { _, _ -> }) {
    init {
        require(capacity >= 1) { "Capacity must be at least 1" }
    }

    private val cache = LinkedHashMap<K, V>(capacity, 0.75f, true)

    operator fun get(key: K): V? = cache[key]

    operator fun set(key: K, value: V) {
        cache[key] = value
        // Remove eldest entry if size exceeds capacity
        if (cache.size > capacity) {
            val eldestKey = cache.keys.firstOrNull()
            if (eldestKey != null) {
                val eldestValue = cache.remove(eldestKey)
                if (eldestValue != null) {
                    onEvict(eldestKey, eldestValue)
                } else {
                    // This shouldn't happen as LinkedHashMap.remove() returns the removed value
                    // But just in case the value was null, we still need to call onEvict
                    onEvict(eldestKey, value)
                }
            }
        }
    }

    fun remove(key: K): V? = cache.remove(key)

    val size: Int
        get() = cache.size

    fun keys(): List<K> = cache.keys.toList()

    operator fun contains(key: K): Boolean = cache.containsKey(key)
}
