sealed class Token {
    abstract val pos: Int
    data class Ident(val name: String, override val pos: Int) : Token()
    data class Str(val value: String, override val pos: Int) : Token()
    data class Num(val value: Double, override val pos: Int) : Token()
    data class Op(val symbol: String, override val pos: Int) : Token()
    data class Paren(val open: Boolean, override val pos: Int) : Token()
}

class TokenizeException(message: String, val pos: Int) : Exception(message)

fun tokenize(input: String): List<Token> {
    val tokens = mutableListOf<Token>()
    var i = 0
    var lastToken: Token? = null

    while (i < input.length) {
        // Skip whitespace
        while (i < input.length && input[i].isWhitespace()) {
            i++
        }
        if (i >= input.length) break

        val start = i

        // Handle parentheses
        if (input[i] == '(' || input[i] == ')') {
            tokens.add(Token.Paren(input[i] == '(', start))
            i++
            lastToken = tokens.last()
            continue
        }

        // Handle operators (longest match first)
        if (i + 1 < input.length && (input[i] == '=' || input[i] == '!' || input[i] == '<' || input[i] == '>')) {
            if (input[i] == '=' && i + 1 < input.length && input[i + 1] == '=') {
                tokens.add(Token.Op("==", start))
                i += 2
                lastToken = tokens.last()
                continue
            }
            if (input[i] == '!' && i + 1 < input.length && input[i + 1] == '=') {
                tokens.add(Token.Op("!=", start))
                i += 2
                lastToken = tokens.last()
                continue
            }
            if (input[i] == '<' && i + 1 < input.length && input[i + 1] == '=') {
                tokens.add(Token.Op("<=", start))
                i += 2
                lastToken = tokens.last()
                continue
            }
            if (input[i] == '>' && i + 1 < input.length && input[i + 1] == '=') {
                tokens.add(Token.Op(">=", start))
                i += 2
                lastToken = tokens.last()
                continue
            }
            if (input[i] == '&' && i + 1 < input.length && input[i + 1] == '&') {
                tokens.add(Token.Op("&&", start))
                i += 2
                lastToken = tokens.last()
                continue
            }
            if (input[i] == '|' && i + 1 < input.length && input[i + 1] == '|') {
                tokens.add(Token.Op("||", start))
                i += 2
                lastToken = tokens.last()
                continue
            }
            // Single-character operators
            tokens.add(Token.Op(input[i].toString(), start))
            i++
            lastToken = tokens.last()
            continue
        }

        // Handle identifiers
        if (input[i].isLetter() || input[i] == '_') {
            var j = i
            while (j < input.length && (input[j].isLetterOrDigit() || input[j] == '_' || input[j] == '.')) {
                j++
