            // Handle negative numbers only when valid
            if (input[i] == '-') {
                i++ // skip the minus sign for now
                // But if it's followed by something other than a digit or '.', it's invalid
                if (i >= input.length || (!input[i].isDigit() && input[i] != '.')) {
                    throw TokenizeException("Invalid character '-' at position $start", start)
                }
