def parse_field_value(value: str, field_range: Tuple[int, int], name_map: dict = None) -> Set[int]:
    """Parse a single field value and return the set of valid values."""
    try:
        if name_map:
            value = value.upper()
            for name, num in name_map.items():
                value = value.replace(name, str(num))

        if value == '*':
            return set(range(field_range[0], field_range[1] + 1))

        values = set()
        items = value.split(',')

        for item in items:
            item = item.strip()
            if '/' in item:
                base, step_str = item.split('/')
                try:
                    step = int(step_str)
                    if step == 0:
                        raise ValueError("Step cannot be zero")
                except ValueError:
                    raise ValueError(f"Invalid step value: {step_str}")

                if base == '*':
                    start = field_range[0]
                else:
                    start = parse_field_value(base, field_range, name_map)
                    if len(start) != 1:
                        raise ValueError(f"Step with range not supported for start: {item}")
                    start = min(start)

                # Generate values starting from start to max with step
                for v in range(start, field_range[1] + 1, step):
                    if v >= field_range[0] and v <= field_range[1]:
                        values.add(v)
            else:
                if '-' in item:
                    # Range
                    parts = item.split('-')
                    if len(parts) != 2:
                        raise ValueError(f"Invalid range: {item}")
                    try:
                        start_val = int(parts[0])
                        end_val = int(parts[1])
                    except ValueError:
                        # Try to parse names
                        start_val = parse_field_value(parts[0], field_range, name_map)
                        end_val = parse_field_value(parts[1], field_range, name_map)
                        if len(start_val) != 1 or len(end_val) != 1:
                            raise ValueError(f"Invalid range with names: {item}")
                        start_val = min(start_val)
                        end_val = min(end_val)
                    else:
                        if start_val > end_val:
                            raise ValueError(f"Range start ({start_val}) > end ({end_val})")

                    for v in range(start_val, end_val + 1):
                        if v >= field_range[0] and v <= field_range[1]:
                            values.add(v)
                else:
                    # Single value
                    try:
                        v = int(item)
                        if v < field_range[0] or v > field_range[1]:
                            raise ValueError(f"Value {v} out of range [{field_range[0]}, {field_range[1]}]")
                        values.add(v)
