                        else:
                            raise ValueError(f"Invalid value: {item}")
        return values
    except Exception as e:
        if isinstance(e, ValueError):
            raise
        else:
            raise ValueError(f"Error parsing field value '{value}': {str(e)}")

def parse_cron_expression(expr: str) -> Tuple[Set[int], Set[int], Set[int], Set[int], Set[int]]:
    """Parse a cron expression and return sets of valid values for each field."""
    fields = expr.strip().split()
    if len(fields) != 5:
        raise ValueError(f"Cron expression must have exactly 5 fields, got {len(fields)}")

    try:
        minutes = parse_field_value(fields[0], MINUTE_RANGE)
        hours = parse_field_value(fields[1], HOUR_RANGE)
        dom = parse_field_value(fields[2], DOM_RANGE)
        months = parse_field_value(fields[3], MONTH_RANGE, MONTH_NAMES)
        dow = parse_field_value(fields[4], DOW_RANGE, DAY_NAMES)

