MINUTE_RANGE = (0, 59)
HOUR_RANGE = (0, 23)
DOM_RANGE = (1, 31)
MONTH_RANGE = (1, 12)
DOW_RANGE = (0, 6)  # 0=Sunday, 1=Monday, ..., 6=Saturday

# Month and day name mappings
MONTH_NAMES = {
    'JAN': 1, 'FEB': 2, 'MAR': 3, 'APR': 4, 'MAY': 5, 'JUN': 6,
    'JUL': 7, 'AUG': 8, 'SEP': 9, 'OCT': 10, 'NOV': 11, 'DEC': 12
}
DAY_NAMES = {
    'SUN': 0, 'MON': 1, 'TUE': 2, 'WED': 3, 'THU': 4, 'FRI': 5, 'SAT': 6
}

def parse_field_value(value: str, field_range: tuple, name_map: dict = None) -> Set[int]:
    """Parse a single field value and return the set of valid values."""
    try:
        value = value.strip()

        # Handle name mapping if provided
        if name_map:
            upper_value = value.upper()
            for name, num in name_map.items():
                upper_value = upper_value.replace(name, str(num))
            value = upper_value

        if value == '*':
            return set(range(field_range[0], field_range[1] + 1))

        values = set()
        items = value.split(',')

        for item in items:
            item = item.strip()
            if '/' in item:
                base, step_str = item.split('/')
                try:
                    step = int(step_str)
                    if step <= 0:
                        raise ValueError("Step cannot be zero or negative")
                except ValueError:
                    raise ValueError(f"Invalid step value: {step_str}")

                if base == '*':
                    start = field_range[0]
                    end = field_range[1]
                    for v in range(start, end + 1, step):
                        values.add(v)
                else:
                    # Parse the base part (could be a range or single value)
                    try:
                        base_values = parse_field_value(base, field_range, name_map)
                        if len(base_values) == 1:
                            start = min(base_values)
                            end = field_range[1]
                            for v in range(start, end + 1, step):
                                values.add(v)
                        else:
                            # Handle range case with step
                            start = min(base_values)
                            end = max(base_values)
                            for v in range(start, end + 1, step):
                                values.add(v)
                    except Exception as e:
                        raise ValueError(f"Error parsing step expression {item}: {str(e)}")
            else:
                if '-' in item:
                    # Range
                    parts = item.split('-')
                    if len(parts) != 2:
                        raise ValueError(f"Invalid range: {item}")
                    try:
                        start_val = int(parts[0])
                        end_val = int(parts[1])
                    except ValueError:
                        raise ValueError(f"Invalid range values: {item}")

                    if start_val > end_val:
                        raise ValueError(f"Range start ({start_val}) > end ({end_val})")

                    for v in range(start_val, end_val + 1):
                        if v >= field_range[0] and v <= field_range[1]:
                            values.add(v)
                else:
                    # Single value
                    try:
                        v = int(item)
                        if v < field_range[0] or v > field_range[1]:
                            raise ValueError(f"Value {v} out of range [{field_range[0]}, {field_range[1]}]")
                        values.add(v)
                    except ValueError:
                        # Try name mapping
                        if name_map:
                            upper_item = item.upper()
                            if upper_item in name_map:
                                v = name_map[upper_item]
                                if v < field_range[0] or v > field_range[1]:
                                    raise ValueError(f"Value {v} out of range [{field_range[0]}, {field_range[1]}]")
                                values.add(v)
                            else:
                                raise ValueError(f"Unknown name: {item}")
                        else:
                            raise ValueError(f"Invalid value: {item}")
        return values
    except ValueError as e:
        raise

def parse_cron_expression(expr: str) -> tuple:
    """Parse a cron expression and return sets of valid values for each field."""
    fields = expr.strip().split()
    if len(fields) != 5:
        raise ValueError(f"Cron expression must have exactly 5 fields, got {len(fields)}")

    try:
        minutes = parse_field_value(fields[0], MINUTE_RANGE)
        hours = parse_field_value(fields[1], HOUR_RANGE)
        dom = parse_field_value(fields[2], DOM_RANGE)
        months = parse_field_value(fields[3], MONTH_RANGE, MONTH_NAMES)
        dow = parse_field_value(fields[4], DOW_RANGE, DAY_NAMES)

        # Normalize DOW 7 to 0 (both represent Sunday)
        if 7 in dow:
            dow.discard(7)
            dow.add(0)

        # Validate day-of-month values
        if not dom or max(dom) > 31 or min(dom) < 1:
            raise ValueError("Day-of-month values must be in range 1-31")

        return minutes, hours, dom, months, dow
    except ValueError as e:
        raise

def matches_cron(dt: datetime.datetime, minutes: set, hours: set, dom: set, months: set, dow: set, dom_restricted: bool, dow_restricted: bool) -> bool:
    """Check if datetime matches the cron expression."""
    # Check month
    if dt.month not in months:
        return False

    # Check hour and minute
    if dt.hour not in hours or dt.minute not in minutes:
        return False

    # Get weekday in cron format (0=Sunday, 1=Monday, ..., 6=Saturday)
    cron_weekday = (dt.weekday() + 1) % 7

    day_of_month_matches = dt.day in dom
    day_of_week_matches = cron_weekday in dow

    # Vixie cron rule:
    # If both dom and dow are restricted (not *), match if EITHER matches
    # Otherwise, both must match
    if dom_restricted and dow_restricted:
        return day_of_month_matches or day_of_week_matches
    else:
        return day_of_month_matches and day_of_week_matches

def next_fire(expr: str, after: datetime.datetime) -> datetime.datetime:
    """Return the earliest datetime strictly after `after` that matches the cron expression."""
    try:
        minutes, hours, dom, months, dow = parse_cron_expression(expr)

        # Determine if fields are restricted (not *)
        dom_restricted = dom != set(range(DOM_RANGE[0], DOM_RANGE[1] + 1))
        dow_restricted = dow != set(range(DOW_RANGE[0], DOW_RANGE[1] + 1))

        # Start from the next minute after 'after'
        candidate = after.replace(second=0, microsecond=0) + datetime.timedelta(minutes=1)

        # Limit to 5 years
        max_date = after.replace(year=after.year + 5)

        # Process year by year
        while candidate < max_date:
            # Get days in the current month
            if candidate.month == 12:
                days_in_month = 31
                next_month = 1
                next_year = candidate.year + 1
            else:
                next_month = candidate.month + 1
                days_in_month = (datetime.datetime(candidate.year, next_month, 1) - datetime.timedelta(days=1)).day

            # Get valid days in this month that are in the dom set
            valid_days = [d for d in dom if d <= days_in_month]
            if not valid_days:
                # Move to next month
                candidate = datetime.datetime(next_year if next_month == 1 else candidate.year, next_month, 1, 0, 0)
                continue

            # If we're past the last valid day, move to next month
            if candidate.day > valid_days[-1]:
                candidate = datetime.datetime(next_year if next_month == 1 else candidate.year, next_month, 1, 0, 0)
                continue

            # Find first valid day >= candidate.day
            day_idx = 0
            while day_idx < len(valid_days) and valid_days[day_idx] < candidate.day:
                day_idx += 1
            if day_idx >= len(valid_days):
                candidate = datetime.datetime(next_year if next_month == 1 else candidate.year, next_month, 1, 0, 0)
                continue

            candidate_day = valid_days[day_idx]
            candidate = candidate.replace(day=candidate_day, hour=0, minute=0)

            # Now iterate over days
            while candidate.month in months and candidate < max_date:
                # Get days in the current month
                if candidate.month == 12:
                    days_in_month = 31
                else:
                    next_month = candidate.month + 1
                    days_in_month = (datetime.datetime(candidate.year, next_month, 1) - datetime.timedelta(days=1)).day

                # Check if current day is valid
                if candidate.day > days_in_month or candidate.day not in dom:
                    break

                # Check day of week
                cron_weekday = (candidate.weekday() + 1) % 7

                # Vixie cron rule
                if dom_restricted and dow_restricted:
                    day_valid = candidate.day in dom or cron_weekday in dow
                else:
                    day_valid = candidate.day in dom and cron_weekday in dow

                if not day_valid:
                    # Advance to next day
                    candidate = candidate + datetime.timedelta(days=1)
                    continue

                # Try to find matching hour
                found = False
                for hour in sorted(hours):
                    if hour > candidate.hour:
                        candidate = candidate.replace(hour=hour, minute=0)
                        found = True
                        break
                    elif hour == candidate.hour:
                        # Try to find matching minute
                        for minute in sorted(minutes):
                            if minute > candidate.minute:
                                candidate = candidate.replace(minute=minute)
                                found = True
                                break
                            elif minute == candidate.minute:
                                # Found exact match, but need strictly after 'after'
                                if candidate > after:
                                    return candidate
                                else:
                                    # Move to next minute
                                    candidate = candidate.replace(minute=minute+1) if minute < 59 else candidate.replace(hour=hour+1, minute=0)
                                    if candidate.hour > 23:
                                        candidate = candidate.replace(hour=0) + datetime.timedelta(days=1)
                                    found = True
                                    break
                        if found:
                            break

                if not found:
                    # Advance to next day
                    candidate = candidate + datetime.timedelta(days=1)
                    continue

                # If we moved to a new day, continue loop
                if candidate.hour == 0 and candidate.minute == 0:
                    continue

                # If minute was 59 and we advanced hour, make sure hour is valid
                if candidate.minute > 59:
                    candidate = candidate.replace(minute=0)
                    if candidate.hour > 23:
                        candidate = candidate.replace(hour=0) + datetime.timedelta(days=1)

            # Move to next month
            if candidate.month == 12:
                candidate = datetime.datetime(candidate.year + 1, 1, 1, 0, 0)
            else:
                candidate = datetime.datetime(candidate.year, candidate.month + 1, 1, 0, 0)

        raise ValueError("No matching time found within 5 years")

    except ValueError as e:
        if "No matching time found" in str(e):
            raise
        raise
