def flatten(obj, sep="."):
    """
    Flatten a nested dictionary/list structure into a flat dictionary with path keys.

    Args:
        obj: The object to flatten (must be a dict at the top level)
        sep: Separator to use between path segments (default: ".")

    Returns:
        dict: A flattened dictionary with path keys

    Raises:
        TypeError: If the top-level object is not a dict
    """
    if not isinstance(obj, dict):
        raise TypeError("Top-level object must be a dict")

    result = {}

    def _flatten(current, path_parts):
        # If current is a dict, process each key-value pair
        if isinstance(current, dict):
            if not current:  # Empty dict - keep as leaf value
                result[sep.join(path_parts)] = current
                return

            for key, value in current.items():
                # Check that key is a string and doesn't contain separator
                if not isinstance(key, str):
                    raise ValueError("Dictionary keys must be strings")
                if sep in key:
                    raise ValueError(f"Key '{key}' contains separator '{sep}'")

                new_path = path_parts + [key]
                _flatten(value, new_path)

        # If current is a list, process each item
        elif isinstance(current, list):
            if not current:  # Empty list - keep as leaf value
                result[sep.join(path_parts)] = current
                return

            for i, item in enumerate(current):
                new_path = path_parts + [str(i)]
                _flatten(item, new_path)

        # Otherwise it's a leaf value
        else:
            result[sep.join(path_parts)] = current

    _flatten(obj, [])
    return result


def unflatten(flat, sep="."):
    """
    Unflatten a flat dictionary with path keys into a nested structure.

    Args:
        flat: A flat dictionary with path keys
        sep: Separator used between path segments (default: ".")

    Returns:
        dict: A nested structure with dicts and lists

    Raises:
        ValueError: If there are conflicts or list indices are invalid
    """
    result = {}

    # Validate all keys are strings
    for key in flat.keys():
        if not isinstance(key, str):
            raise ValueError("All keys in flat dict must be strings")

    # Sort keys to ensure proper order of processing (shorter paths first)
    # This is necessary to handle conflicts properly
    sorted_keys = sorted(flat.keys(), key=lambda x: x.count(sep))

    for key in sorted_keys:
        path_parts = key.split(sep)
        current = result

        # Traverse the path
        for i, part in enumerate(path_parts):
            is_last = (i == len(path_parts) - 1)

            # Check if part is a potential list index (non-negative integer without leading zeros)
            is_index = part.isdigit() and (part == "0" or not part.startswith("0"))

            if is_last:
                # This is the final segment - set the value
                if is_index:
                    # This path expects to end in a list
                    index = int(part)

                    # Check if current is already a list or dict that would conflict
                    if isinstance(current, dict):
                        # If we're supposed to be a list, but current is a dict, that's a conflict
                        if part in current:
                            raise ValueError(f"Conflict: '{key}' conflicts with existing key '{sep.join(path_parts[:i])}'")
                        # Convert to list if needed
                        if not isinstance(current, list):
                            # If current has other string keys, we can't convert to list
                            if current:
                                raise ValueError(f"Conflict: cannot create list at '{key}' because other keys exist in the same dict")
                            current.clear()
                            current.append(None)  # Initialize with one element
                    elif not isinstance(current, list):
                        # If current is not list or dict, there's a conflict
                        raise ValueError(f"Conflict: '{key}' conflicts with existing value")

                    # Extend list if needed
                    if index >= len(current):
                        current.extend([None] * (index - len(current) + 1))

                    current[index] = flat[key]

                else:
                    # This path expects to end in a dict
                    if not isinstance(current, dict):
                        raise ValueError(f"Conflict: '{key}' conflicts with existing non-dict value")

                    if part in current:
                        raise ValueError(f"Conflict: '{key}' conflicts with existing key '{sep.join(path_parts[:i])}'")

                    current[part] = flat[key]
            else:
                # Not the last segment - navigate deeper
                next_part = path_parts[i + 1]
                next_is_index = next_part.isdigit() and (next_part == "0" or not next_part.startswith("0"))

                if is_index:
                    # Current path segment is a list index
                    index = int(part)

                    # Ensure current is a list
                    if not isinstance(current, list):
                        # If current is a dict that's empty, we can convert it to a list
                        if isinstance(current, dict) and not current:
                            current = []
                        else:
                            raise ValueError(f"Conflict: cannot navigate to '{sep.join(path_parts[:i+1])}' because existing value is not a list or dict")

                    # Extend list if needed
                    if index >= len(current):
                        current.extend([None] * (index - len(current) + 1))

                    # Set the next level if needed
                    if current[index] is None:
                        if next_is_index:
                            current[index] = []
                        else:
                            current[index] = {}
                    current = current[index]
                else:
                    # Current path segment is a dict key
                    if not isinstance(current, dict):
                        # If current is a list that's empty, we can convert it to a dict
                        if isinstance(current, list) and not current:
                            current = {}
                        else:
                            raise ValueError(f"Conflict: cannot navigate to '{sep.join(path_parts[:i+1])}' because existing value is not a list or dict")

                    if part not in current:
                        # Create next level
                        next_part = path_parts[i + 1]
                        if next_part.isdigit() and (next_part == "0" or not next_part.startswith("0")):
                            current[part] = []
                        else:
                            current[part] = {}
                    current = current[part]

    # Validate that lists are dense (no gaps)
    def validate_structure(obj):
        if isinstance(obj, dict):
            for key, value in obj.items():
                if not isinstance(key, str):
                    raise ValueError(f"Invalid key in dict: {key}")
                validate_structure(value)
        elif isinstance(obj, list):
            n = len(obj)
            for i, item in enumerate(obj):
                # Check for gaps
                if item is None:
                    raise ValueError(f"List has gaps at index {i}")
                validate_structure(item)

    validate_structure(result)

    return result
