import re
from typing import Union, Optional

class Token:
    def __init__(self, type_: str, value: Union[str, float, int, None] = None):
        self.type = type_
        self.value = value

    def __repr__(self):
        return f"Token({self.type}, {self.value})"

class Lexer:
    def __init__(self, text: str):
        self.text = text
        self.pos = 0
        self.tokens = []
        self.current_char = self.text[0] if self.text else None

    def advance(self):
        self.pos += 1
        if self.pos < len(self.text):
            self.current_char = self.text[self.pos]
        else:
            self.current_char = None

    def skip_whitespace(self):
        while self.current_char is not None and self.current_char.isspace():
            self.advance()

    def number(self):
        start_pos = self.pos
        has_dot = False
        while self.current_char is not None and (self.current_char.isdigit() or self.current_char == '.'):
            if self.current_char == '.':
                if has_dot:
                    raise SyntaxError("Invalid number format")
                has_dot = True
            self.advance()

        num_str = self.text[start_pos:self.pos]

        # Handle cases like '.', '2.' or '.5'
        if num_str == '.':
            raise SyntaxError("Invalid number format")

        if has_dot:
            return float(num_str)
        else:
            return int(num_str)

    def identifier(self):
        start_pos = self.pos
        while self.current_char is not None and (self.current_char.isalnum() or self.current_char == '_'):
            self.advance()

        identifier = self.text[start_pos:self.pos]
        return identifier

    def tokenize(self):
        while self.current_char is not None:
            if self.current_char.isspace():
                self.skip_whitespace()
                continue

            # Numbers
            if self.current_char.isdigit() or (self.current_char == '.' and 
                self.pos + 1 < len(self.text) and self.text[self.pos + 1].isdigit()):
                value = self.number()
                self.tokens.append(Token("NUMBER", value))
                continue

            # Identifiers and keywords
            if self.current_char.isalpha() or self.current_char == '_':
                ident = self.identifier()
                if ident in ("true", "false"):
                    self.tokens.append(Token("BOOL", True if ident == "true" else False))
                elif ident == "min" or ident == "max" or ident == "abs":
                    self.tokens.append(Token("FUNCTION", ident))
                else:
                    self.tokens.append(Token("IDENTIFIER", ident))
                continue

            # Operators and delimiters
            if self.current_char == '?':
                self.tokens.append(Token("QUESTION"))
                self.advance()
            elif self.current_char == ':':
                self.tokens.append(Token("COLON"))
                self.advance()
            elif self.current_char == '|':
                if self.pos + 1 < len(self.text) and self.text[self.pos + 1] == '|':
                    self.tokens.append(Token("OR"))
                    self.advance()
                    self.advance()
                else:
                    raise SyntaxError("Invalid token: |")
            elif self.current_char == '&':
                if self.pos + 1 < len(self.text) and self.text[self.pos + 1] == '&':
                    self.tokens.append(Token("AND"))
                    self.advance()
                    self.advance()
                else:
                    raise SyntaxError("Invalid token: &")
            elif self.current_char == '!':
                if self.pos + 1 < len(self.text) and self.text[self.pos + 1] == '=':
                    self.tokens.append(Token("NEQ"))
                    self.advance()
                    self.advance()
                else:
                    self.tokens.append(Token("NOT"))
                    self.advance()
            elif self.current_char == '=':
                if self.pos + 1 < len(self.text) and self.text[self.pos + 1] == '=':
                    self.tokens.append(Token("EQ"))
                    self.advance()
                    self.advance()
                else:
                    raise SyntaxError("Invalid token: =")
            elif self.current_char == '<':
                if self.pos + 1 < len(self.text):
                    if self.text[self.pos + 1] == '=':
                        self.tokens.append(Token("LTE"))
                        self.advance()
                        self.advance()
                    elif self.text[self.pos + 1] == '>':
                        self.tokens.append(Token("NEQ"))
                        self.advance()
                        self.advance()
                    else:
                        self.tokens.append(Token("LT"))
                        self.advance()
                else:
                    self.tokens.append(Token("LT"))
                    self.advance()
            elif self.current_char == '>':
                if self.pos + 1 < len(self.text) and self.text[self.pos + 1] == '=':
                    self.tokens.append(Token("GTE"))
                    self.advance()
                    self.advance()
                else:
                    self.tokens.append(Token("GT"))
                    self.advance()
            elif self.current_char == '+':
                self.tokens.append(Token("PLUS"))
                self.advance()
            elif self.current_char == '-':
                self.tokens.append(Token("MINUS"))
                self.advance()
            elif self.current_char == '*':
                self.tokens.append(Token("MUL"))
                self.advance()
            elif self.current_char == '/':
                self.tokens.append(Token("DIV"))
                self.advance()
            elif self.current_char == '%':
                self.tokens.append(Token("MOD"))
                self.advance()
            elif self.current_char == '^':
                self.tokens.append(Token("POW"))
                self.advance()
            elif self.current_char == '(':
                self.tokens.append(Token("LPAREN"))
                self.advance()
            elif self.current_char == ')':
                self.tokens.append(Token("RPAREN"))
                self.advance()
            elif self.current_char == ',':
                self.tokens.append(Token("COMMA"))
                self.advance()
            else:
                raise SyntaxError(f"Unexpected character: {self.current_char}")

        return self.tokens

class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def current_token(self):
        return self.tokens[self.pos] if self.pos < len(self.tokens) else Token("EOF")

    def peek_token(self):
        return self.tokens[self.pos + 1] if self.pos + 1 < len(self.tokens) else Token("EOF")

    def advance(self):
        self.pos += 1

    def parse(self):
        if not self.tokens:
            raise SyntaxError("Empty input")

        result = self.parse_conditional()

        if self.current_token().type != "EOF":
            raise SyntaxError("Unexpected trailing tokens")

        return result

    def parse_conditional(self):
        expr = self.parse_logical_or()

        if self.current_token().type == "QUESTION":
            self.advance()  # consume '?'
            then_expr = self.parse_conditional()  # parse true branch
            if self.current_token().type != "COLON":
                raise SyntaxError("Expected ':' after conditional")
            self.advance()  # consume ':'
            else_expr = self.parse_conditional()  # parse false branch

            return ("conditional", expr, then_expr, else_expr)

        return expr

    def parse_logical_or(self):
        left = self.parse_logical_and()

        while self.current_token().type == "OR":
            self.advance()
            right = self.parse_logical_and()
            left = ("or", left, right)

        return left

    def parse_logical_and(self):
        left = self.parse_comparison()

        while self.current_token().type == "AND":
            self.advance()
            right = self.parse_comparison()
            left = ("and", left, right)

        return left

    def parse_comparison(self):
        left = self.parse_additive()

        while self.current_token().type in ("EQ", "NEQ", "LT", "LTE", "GT", "GTE"):
            op = self.current_token().type
            self.advance()
            right = self.parse_additive()

            # Check for chaining: a < b < c is invalid
            if self.current_token().type in ("EQ", "NEQ", "LT", "LTE", "GT", "GTE"):
                raise SyntaxError("Comparison chaining is not allowed")

            left = ("comparison", op, left, right)

        return left

    def parse_additive(self):
        left = self.parse_multiplicative()

        while self.current_token().type in ("PLUS", "MINUS"):
            op = self.current_token().type
            self.advance()
            right = self.parse_multiplicative()
            left = ("additive", op, left, right)

        return left

    def parse_multiplicative(self):
        left = self.parse_unary()

        while self.current_token().type in ("MUL", "DIV", "MOD"):
            op = self.current_token().type
            self.advance()
            right = self.parse_unary()
            left = ("multiplicative", op, left, right)

        return left

    def parse_unary(self):
        if self.current_token().type == "MINUS":
            self.advance()
            return ("unary", "-", self.parse_unary())
        elif self.current_token().type == "PLUS":
            self.advance()
            return ("unary", "+", self.parse_unary())
