        if start >= end:
            return
        i = bisect.bisect_left(self._iv, (start, end))
        # Check if we need to merge with the previous interval
        if i > 0 and self._iv[i - 1][1] >= start:
            i -= 1
        j = i
        # Merge all overlapping intervals (touching intervals merge too)
        while j < len(self._iv) and self._iv[j][0] <= end:
            start = min(start, self._iv[j][0])
            end = max(end, self._iv[j][1])
            j += 1
        self._iv[i:j] = [(start, end)]

    def remove(self, start, end):
        # Ignore empty intervals
        if start >= end:
            return
        out = []
        for s, e in self._iv:
            # If no overlap, keep the interval
            if e <= start or s >= end:
                out.append((s, e))
                continue
            # If there's a part before the removal range
            if s < start:
                out.append((s, start))
            # If there's a part after the removal range
            if e > end:
                out.append((end, e))
        self._iv = out

    def contains(self, x):
        # Find the interval that could contain x
        i = bisect.bisect_left(self._iv, (x, x))
        # Check if x is in interval i: s <= x < e
        if i < len(self._iv) and self._iv[i][0] <= x < self._iv[i][1]:
            return True
        return False

    def free(self, lo, hi):
        # Handle invalid range
        if lo >= hi:
            return []

        gaps = []
        cur = lo

        for s, e in self._iv:
            # If we've passed hi, we're done
            if cur >= hi:
                break
            # If current interval starts after cur, we have a gap from cur to min(s, hi)
            if s > cur:
                gaps.append((cur, min(s, hi)))
                cur = min(s, hi)
            # Move cur to the end of the current interval or hi, whichever is smaller
            cur = max(cur, e)

        # Add remaining gap if any
        if cur < hi:
            gaps.append((cur, hi))

        return gaps

    def __iter__(self):
        return iter(self._iv)

    def __len__(self):
        return len(self._iv)
