import heapq
from collections import defaultdict

def route(grid: list[str]) -> tuple[int, str] | None:
    # Input validation
    if not grid:
        raise ValueError("Grid cannot be empty")

    rows = len(grid)
    cols = len(grid[0])

    # Check for ragged rows
    for row in grid:
        if len(row) != cols:
            raise ValueError("Grid has ragged rows")

    # Count occurrences of special characters
    start_count = 0
    end_count = 0
    letter_counts = defaultdict(int)
    valid_chars = set('.#SE')
    for row in grid:
        for cell in row:
            if cell == 'S':
                start_count += 1
            elif cell == 'E':
                end_count += 1
            elif cell.islower():
                letter_counts[cell] += 1
            elif cell.isdigit():
                valid_chars.add(cell)
            elif cell == '.' or cell == '#':
                valid_chars.add(cell)
            else:
                raise ValueError(f"Unknown character: {cell}")

    # Validate S and E counts
    if start_count != 1:
        raise ValueError(f"Expected exactly one 'S', found {start_count}")
    if end_count != 1:
        raise ValueError(f"Expected exactly one 'E', found {end_count}")

    # Validate letter counts (each letter must appear 0 or 2 times)
    for letter, count in letter_counts.items():
        if count != 2:
            raise ValueError(f"Letter '{letter}' appears {count} times, expected 0 or 2")

    # Find start, end, and teleport pads positions
    start = None
    end = None
    pads = defaultdict(list)  # letter -> [position1, position2]

    for r in range(rows):
        for c in range(cols):
            cell = grid[r][c]
            if cell == 'S':
                start = (r, c)
            elif cell == 'E':
                end = (r, c)
            elif cell.islower():
                pads[cell].append((r, c))

    # Cost function
    def get_cost(r, c):
        cell = grid[r][c]
        if cell == 'S' or cell == 'E' or cell == '.' or cell.islower():
            return 1
        elif cell.isdigit():
            return int(cell)
        else:  # wall or other invalid (shouldn't happen due to validation)
            return float('inf')

    # Directions in order: D, L, R, T, U (for lexicographic order)
    # Note: T is special and handled separately
    directions = [
        (1, 0, 'D'),
        (0, -1, 'L'),
        (0, 1, 'R'),
        (-1, 0, 'U')
    ]

    # Dijkstra's algorithm
    # State: (cost, row, col, moves_string)
    # Priority: (cost, moves_string) where moves_string comparison is lexicographic
    # We use tuple (cost, moves) as key for priority comparison

    # Initialize priority queue
    pq = []
    heapq.heappush(pq, (0, start[0], start[1], ""))  # (cost, row, col, path)

    # Best cost to reach (row, col)
    best_cost = {}
    best_cost[(start[0], start[1])] = 0

    # Best path string to reach (row, col) with minimal cost
    best_path = {}
    best_path[(start[0], start[1])] = ""

    while pq:
        cost, r, c, path = heapq.heappop(pq)

        # Check if we reached the end
        if (r, c) == end:
            return (cost, path)

        # Skip if we have a better way already
        if cost > best_cost.get((r, c), float('inf')):
            continue
        if cost == best_cost.get((r, c), float('inf')) and path > best_path.get((r, c), ""):
            continue

        # Try orthogonal moves
        for dr, dc, direction in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                cell = grid[nr][nc]
                if cell == '#':
                    continue

                move_cost = get_cost(nr, nc)
                new_cost = cost + move_cost
                new_path = path + direction

                # Check if this is a better way to (nr, nc)
                if new_cost < best_cost.get((nr, nc), float('inf')):
                    best_cost[(nr, nc)] = new_cost
                    best_path[(nr, nc)] = new_path
                    heapq.heappush(pq, (new_cost, nr, nc, new_path))
                elif new_cost == best_cost.get((nr, nc), float('inf')) and new_path < best_path.get((nr, nc), ""):
                    best_path[(nr, nc)] = new_path
                    heapq.heappush(pq, (new_cost, nr, nc, new_path))

        # Try teleport if on a pad
        cell = grid[r][c]
        if cell.islower():
            # Find the other pad with the same letter
            other_pad = None
            for pad_pos in pads[cell]:
                if pad_pos != (r, c):
                    other_pad = pad_pos
                    break

            if other_pad:
                nr, nc = other_pad
                move_cost = 2  # teleport costs 2
                new_cost = cost + move_cost
                new_path = path + 'T'

                # Check if this is a better way to (nr, nc)
                if new_cost < best_cost.get((nr, nc), float('inf')):
                    best_cost[(nr, nc)] = new_cost
                    best_path[(nr, nc)] = new_path
                    heapq.heappush(pq, (new_cost, nr, nc, new_path))
                elif new_cost == best_cost.get((nr, nc), float('inf')) and new_path < best_path.get((nr, nc), ""):
                    best_path[(nr, nc)] = new_path
                    heapq.heappush(pq, (new_cost, nr, nc, new_path))

    # End is unreachable
    return None
