def load_ini(text: str) -> dict[str, dict[str, str]]:
    lines = text.splitlines()
    result: dict[str, dict[str, str]] = {}
    current_section: str = ""
    prev_key: str | None = None
    prev_line_num: int | None = None

    # First pass: parse the file into a raw structure
    i = 0
    while i < len(lines):
        line_num = i + 1
        line = lines[i]
        stripped_line = line.strip()

        # Skip blank lines
        if not stripped_line:
            prev_key = None
            i += 1
            continue

        # Skip comment lines (lines starting with # or ; after optional whitespace)
        if stripped_line.startswith("#") or stripped_line.startswith(";"):
            prev_key = None
            i += 1
            continue

        # Section header
        if stripped_line.startswith("["):
            if stripped_line.find("]") == -1:
                raise ValueError(f"line {line_num}: unclosed section header")
            # Extract section name (between [ and ])
            section_name = stripped_line[1:stripped_line.find("]")].strip()
            current_section = section_name
            if current_section not in result:
                result[current_section] = {}
            prev_key = None
            i += 1
            continue

        # Entry line (key = value or key: value)
        # Check if it's a continuation line (starts with whitespace) and has a preceding entry
        if line[0].isspace() and prev_key is not None:
            # Continuation line
            # Trim the line and append with newline
            continuation_value = line.strip()
            result[current_section][prev_key] += "\n" + continuation_value
            i += 1
            continue
        elif line[0].isspace() and prev_key is None:
            raise ValueError(f"line {line_num}: continuation line with no preceding entry")

        # Find the separator (= or :)
        separator_pos = -1
        separator_char = ""
        in_quotes = False
        escape_next = False

        # Find first unescaped = or : outside quotes
        for j, char in enumerate(line):
            if escape_next:
                escape_next = False
                continue

            if char == "\\":
                escape_next = True
                continue

            if char == '"':
                in_quotes = not in_quotes
                continue

            if not in_quotes:
                if char == '=' or char == ':':
                    separator_pos = j
                    separator_char = char
                    break

        if separator_pos == -1:
            raise ValueError(f"line {line_num}: missing separator")

        # Extract key and value parts
        key_part = line[:separator_pos].strip()
        value_part = line[separator_pos+1:]

        if not key_part:
            raise ValueError(f"line {line_num}: empty key")

        key = key_part.lower()

        # Process value: handle comments and quotes
        # Remove inline comments unless inside quotes
        in_quotes = False
        escape_next = False
        comment_pos = -1

        for j, char in enumerate(value_part):
            if escape_next:
                escape_next = False
                continue

            if char == "\\":
                if j + 1 < len(value_part) and value_part[j+1] == '"':
                    escape_next = True
                continue

            if char == '"':
                in_quotes = not in_quotes
                continue

            if not in_quotes:
                # Check for comment markers
                if char == ';' or char == '#':
                    # Check if there's whitespace before the comment marker
                    if j == 0 or value_part[j-1].isspace():
                        comment_pos = j
                        break

        if comment_pos != -1:
            value_part = value_part[:comment_pos]

        # Trim the value part
        value_part = value_part.strip()

        # Handle quoted values
        if len(value_part) >= 2 and value_part.startswith('"') and value_part.endswith('"'):
            # Remove quotes and process escapes
            inner_value = value_part[1:-1]
            # Process escapes: \" -> "
            processed_value = []
            j = 0
            while j < len(inner_value):
                if inner_value[j] == '\\' and j + 1 < len(inner_value) and inner_value[j+1] == '"':
                    processed_value.append('"')
                    j += 2
                else:
                    processed_value.append(inner_value[j])
                    j += 1
            value = ''.join(processed_value)
        else:
            value = value_part

        # Ensure section exists
        if current_section not in result:
            result[current_section] = {}

        # Store the value (last wins for repeated keys)
        result[current_section][key] = value
        prev_key = key
        prev_line_num = line_num

        i += 1

    # Remove empty section if no keys
    if "" in result and not result[""]:
        del result[""]

    # Second pass: interpolation
    # We'll need to resolve ${key} and ${section:key} references
    def resolve_value(value: str, section: str, visited: set) -> str:
        if "${" not in value and "$$" not in value:
            return value

        # Replace $$ with placeholder to avoid interference with ${...}
        placeholder = "\x00DOLLAR\x00"
        temp_value = value.replace("$$", placeholder)

        # Find and resolve references
        i = 0
        result_parts = []
        while i < len(temp_value):
            if temp_value[i:i+2] == placeholder:
                result_parts.append('$')
                i += 2
            elif temp_value[i] == '$' and i+1 < len(temp_value) and temp_value[i+1] == '{':
                # Found a reference
                start = i + 2
                end = temp_value.find('}', start)
                if end == -1:
                    raise ValueError(f"line N: unclosed reference")

                ref = temp_value[start:end]
                i = end + 1

                # Parse reference: ${key} or ${section:key}
                if ':' in ref:
                    parts = ref.split(':', 1)
                    if len(parts) != 2:
                        raise ValueError(f"line N: invalid reference format")
                    ref_section, ref_key = parts
                    ref_section = ref_section.strip()
                    ref_key = ref_key.strip()
                else:
                    ref_section = section
                    ref_key = ref.strip()

                # Normalize key to lowercase
                ref_key = ref_key.lower()

                # Check for cycle
                key_tuple = (ref_section, ref_key)
                if key_tuple in visited:
                    raise ValueError(f"cycle detected in interpolation: {ref}")

                # Check if reference exists
                if ref_section not in result or ref_key not in result[ref_section]:
                    raise ValueError(f"line N: undefined reference ${ref}")

                # Recursively resolve
                new_visited = visited | {key_tuple}
                resolved = resolve_value(result[ref_section][ref_key], ref_section, new_visited)
                result_parts.append(resolved)
            else:
                result_parts.append(temp_value[i])
                i += 1

        return ''.join(result_parts)

    # Apply interpolation to all values
    resolved_result: dict[str, dict[str, str]] = {}

    # We need to resolve in an order that ensures dependencies are resolved
    # First, try to detect cycles by checking if any reference is undefined
    # We'll resolve repeatedly until no changes, but detect cycles

    # For each section and key, compute the resolved value
    for section in result:
        resolved_result[section] = {}
        for key in result[section]:
            visited = {(section, key)}
            try:
                resolved_result[section][key] = resolve_value(result[section][key], section, visited)
            except ValueError as e:
                # Replace "line N" with actual line number if possible
                # Since we don't track exact line numbers for references, just raise with generic message
                raise ValueError(f"line N: {str(e).replace('line N: ', '')}")

    return resolved_result
