import re
from functools import cmp_to_key
from typing import List, Optional, Tuple, Union


class Version:
    def __init__(self, major: int, minor: int, patch: int, prerelease: List[Union[str, int]] = None,
                 build: str = None):
        self.major = major
        self.minor = minor
        self.patch = patch
        self.prerelease = prerelease or []
        self.build = build

    def __repr__(self):
        return f"Version({self.major}, {self.minor}, {self.patch}, {self.prerelease}, {self.build})"

    def __str__(self):
        version_str = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            version_str += "-" + ".".join(str(x) for x in self.prerelease)
        if self.build:
            version_str += "+" + self.build
        return version_str

    def __eq__(self, other):
        if not isinstance(other, Version):
            return False
        # Build metadata is ignored for equality
        return (self.major == other.major and
                self.minor == other.minor and
                self.patch == other.patch and
                self.prerelease == other.prerelease)

    def __lt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        # Compare major, minor, patch
        if self.major != other.major:
            return self.major < other.major
        if self.minor != other.minor:
            return self.minor < other.minor
        if self.patch != other.patch:
            return self.patch < other.patch

        # Compare prerelease
        # A version without prerelease is >= one with prerelease
        if not self.prerelease and other.prerelease:
            return False
        if self.prerelease and not other.prerelease:
            return True
        if not self.prerelease and not other.prerelease:
            return False

        # Both have prerelease, compare identifiers
        for i in range(min(len(self.prerelease), len(other.prerelease))):
            self_id = self.prerelease[i]
            other_id = other.prerelease[i]

            # Convert to int if possible for comparison
            self_int = self_id if isinstance(self_id, int) else (int(self_id) if self_id.isdigit() else None)
            other_int = other_id if isinstance(other_id, int) else (int(other_id) if other_id.isdigit() else None)

            # Both numeric
            if self_int is not None and other_int is not None:
                if self_int != other_int:
                    return self_int < other_int
            # Numeric < alphanumeric
            elif self_int is not None and other_int is None:
                return True
            elif self_int is None and other_int is not None:
                return False
            # Both alphanumeric - use ASCII order
            else:
                if str(self_id) != str(other_id):
                    return str(self_id) < str(other_id)

        # Shorter list is smaller if all identifiers compared equal so far
        return len(self.prerelease) < len(other.prerelease)

    def __le__(self, other):
        return self == other or self < other

    def __gt__(self, other):
        return not self <= other

    def __ge__(self, other):
        return not self < other

    def __hash__(self):
        # Build metadata is ignored for hashing
        return hash((self.major, self.minor, self.patch, tuple(self.prerelease)))


def parse(version_str: str) -> Version:
    """Parse a version string into a Version object."""
    if not isinstance(version_str, str):
        raise ValueError("Version must be a string")

    # Strip leading/trailing whitespace
    version_str = version_str.strip()

    # Handle leading 'v' or '='
    if version_str.startswith('v'):
        version_str = version_str[1:]
    if version_str.startswith('='):
        version_str = version_str[1:]
    version_str = version_str.strip()

    if not version_str:
        raise ValueError("Empty version string")

    # Regex for valid SemVer 2.0.0 format
    # MAJOR.MINOR.PATCH[-PRERELEASE][+BUILD]
    # PRERELEASE identifiers: [0-9A-Za-z-]+, non-empty, no leading zeros for numeric parts
    # BUILD metadata: [0-9A-Za-z-]+, non-empty

    # Split into core version, prerelease, and build
    parts = re.split(r'[+\-]', version_str, 2)

    # Base version (MAJOR.MINOR.PATCH)
    core = parts[0]

    # Validate core version parts
    core_parts = core.split('.')
    if len(core_parts) != 3:
        raise ValueError("Invalid version format: must be MAJOR.MINOR.PATCH")

    major_str, minor_str, patch_str = core_parts

    # Check for empty parts
    if not major_str or not minor_str or not patch_str:
        raise ValueError("Invalid version format: empty MAJOR, MINOR, or PATCH")

    # Check for invalid leading zeros (only '0' allowed, not '00', '01', etc.)
    def validate_numeric_part(part, part_name):
        if not re.match(r'^[0-9]+$', part):
            raise ValueError(f"Invalid {part_name} part: {part} - must be numeric")
        if len(part) > 1 and part[0] == '0':
            raise ValueError(f"Invalid {part_name} part: {part} - leading zeros not allowed")
        return int(part)

    major = validate_numeric_part(major_str, "MAJOR")
    minor = validate_numeric_part(minor_str, "MINOR")
    patch = validate_numeric_part(patch_str, "PATCH")

    # Parse prerelease (if present)
    prerelease = []
    if len(parts) >= 2 and '-' in version_str:
        # Find position of '-'
        hyphen_pos = version_str.find('-')
        plus_pos = version_str.find('+')

        # Determine where prerelease ends
        if plus_pos != -1:
            prerelease_str = version_str[hyphen_pos+1:plus_pos]
        else:
            prerelease_str = version_str[hyphen_pos+1:]

        # Split by '.' and validate identifiers
        prerelease_parts = prerelease_str.split('.')
        for part in prerelease_parts:
            if not part:
                raise ValueError("Invalid prerelease: empty identifier")
            if not re.match(r'^[0-9A-Za-z-]+$', part):
                raise ValueError(f"Invalid prerelease identifier: {part}")
            # Check for leading zeros in numeric parts
            if part.isdigit():
                if len(part) > 1 and part[0] == '0':
                    raise ValueError(f"Invalid prerelease identifier: {part} - leading zeros not allowed in numeric identifiers")
                prerelease.append(int(part))
            else:
                prerelease.append(part)

    # Parse build metadata (if present)
    build = None
    if len(parts) == 3 or '+' in version_str:
        plus_pos = version_str.find('+')
        if plus_pos != -1:
            build_str = version_str[plus_pos+1:]
            # Build metadata can have multiple dot-separated parts
            build_parts = build_str.split('.')
            for part in build_parts:
                if not part:
                    raise ValueError("Invalid build metadata: empty identifier")
                if not re.match(r'^[0-9A-Za-z-]+$', part):
                    raise ValueError(f"Invalid build metadata identifier: {part}")
            build = build_str  # Keep original format with dots

    return Version(major, minor, patch, prerelease, build)


def _parse_partial_version(version_str: str) -> Tuple[int, int, int, bool, bool]:
    """Parse a partial version string like '1', '1.2', '1.2.x', '1.2.*', 'X'."""
    version_str = version_str.strip()

    if version_str.lower() == 'x':
        return (0, 0, 0, True, True)

    # Handle wildcards like x or *
    if '.' not in version_str:
        # Just a major number like '1'
        if not version_str.isdigit():
            raise ValueError(f"Invalid partial version: {version_str}")
        if len(version_str) > 1 and version_str[0] == '0':
            raise ValueError(f"Invalid partial version: leading zero in major version")
        return (int(version_str), 0, 0, True, True)

    parts = version_str.split('.')

    # Handle X-ranges like '1.x' or '1.2.*'
    major = None
    minor = None
    patch = None
    wildcard_major = False
    wildcard_minor = False

    if not parts[0].isdigit() and parts[0].lower() != 'x':
        raise ValueError(f"Invalid partial version: major part '{parts[0]}' is not numeric")

    if parts[0].lower() == 'x':
        wildcard_major = True
        major = 0
    else:
        if len(parts[0]) > 1 and parts[0][0] == '0':
            raise ValueError(f"Invalid partial version: leading zero in major version")
        major = int(parts[0])

    if len(parts) >= 2:
        if not parts[1].isdigit() and parts[1].lower() != 'x' and parts[1] != '*':
            raise ValueError(f"Invalid partial version: minor part '{parts[1]}' is not valid")

        if parts[1].lower() in ('x', '*'):
            wildcard_minor = True
            minor = 0
        else:
            if len(parts[1]) > 1 and parts[1][0] == '0':
                raise ValueError(f"Invalid partial version: leading zero in minor version")
            minor = int(parts[1])

    if len(parts) >= 3:
        if not parts[2].isdigit() and parts[2].lower() != 'x' and parts[2] != '*':
            raise ValueError(f"Invalid partial version: patch part '{parts[2]}' is not valid")

        # Only minor and patch can be wildcards
        if parts[2].lower() in ('x', '*'):
            if not wildcard_minor:  # If minor is specified, we can't wildcard patch
                raise ValueError(f"Invalid partial version: cannot wildcard patch without wild-carding minor")
            patch = 0
        else:
            if len(parts[2]) > 1 and parts[2][0] == '0':
                raise ValueError(f"Invalid partial version: leading zero in patch version")
            patch = int(parts[2])

    # If minor is wildcard and patch is specified, that's invalid
    if wildcard_minor and patch is not None:
        raise ValueError(f"Invalid partial version: cannot specify patch when minor is wildcard")

    # If major is wildcard but minor is specified, invalid
    if wildcard_major and (minor is not None or patch is not None):
        raise ValueError(f"Invalid partial version: cannot specify minor/patch when major is wildcard")

    # At least major should be specified
    if major is None:
        raise ValueError(f"Invalid partial version: major version must be specified")

    return (major, minor or 0, patch or 0, wildcard_major, wildcard_minor)


def _create_version_from_partial(major: int, minor: int, patch: int, wildcard_minor: bool, wildcard_patch: bool,
                                 prerelease: List[Union[str, int]] = None, is_upper_bound: bool = False) -> Version:
    """Create a Version object from partial components."""
    if is_upper_bound and wildcard_minor:
        # For upper bound, if minor is wildcard, the next version is major+1
        return Version(major + 1, 0, 0, prerelease)
    elif is_upper_bound and wildcard_patch:
        # For upper bound, if patch is wildcard, the next version is minor+1
        return Version(major, minor + 1, 0, prerelease)
    else:
        return Version(major, minor, patch, prerelease)


def _parse_comparator(range_str: str) -> Tuple[str, Version]:
