            if wildcard_minor:
                version = Version(major + 1, 0, 0, [], None)
            elif minor == 0 and patch == 0:
                version = Version(major, minor + 1, 0, [], None)
            else:
                version = Version(major, minor, patch, [], None)
        elif op == '<=':
            if wildcard_minor:
                version = Version(major + 1, 0, 0, [], None)
                op = '<'
            elif minor == 0 and patch == 0:
                version = Version(major, minor + 1, 0, [], None)
                op = '<'
            else:
                version = Version(major, minor, patch, [], None)

        return [(op, version)]


def _parse_hyphen_range(range_str: str) -> List[Tuple[str, Version]]:
    """Parse a hyphen range like '1.2.3 - 2.3.4'."""
    range_str = range_str.strip()

    if ' - ' not in range_str:
        return _parse_comparator(range_str)

    parts = range_str.split(' - ')
    if len(parts) != 2:
        raise ValueError("Invalid hyphen range: must be exactly two versions separated by ' - '")

    lower_str = parts[0].strip()
    upper_str = parts[1].strip()

    if not lower_str or not upper_str:
        raise ValueError("Invalid hyphen range: empty lower or upper bound")

    # Parse lower bound
    try:
        lower_version = parse(lower_str)
        lower_op = '>='
    except ValueError:
        # Try partial version for lower bound
        major, minor, patch, wildcard_major, wildcard_minor = _parse_partial_version(lower_str)
        lower_version = Version(major, minor, patch, [], None)
        lower_op = '>='

    # Parse upper bound
    try:
        upper_version = parse(upper_str)
        upper_op = '<='
    except ValueError:
        # Try partial version for upper bound
        major, minor, patch, wildcard_major, wildcard_minor = _parse_partial_version(upper_str)
        upper_version = Version(major, minor, patch, [], None)
        upper_op = '<='

    # Adjust for partial upper bound: if upper has wildcards, make it exclusive of next level
    if 'x' in upper_str.lower() or '*' in upper_str:
        if wildcard_minor or wildcard_major:
            # If upper bound has wildcards, convert to exclusive
            if wildcard_minor:
                upper_version = Version(major + 1, 0, 0, [], None)
                upper_op = '<'
            elif minor == 0 and patch == 0:
                upper_version = Version(major, minor + 1, 0, [], None)
                upper_op = '<'
            else:
                upper_version = Version(major, minor, patch + 1, [], None)
                upper_op = '<'
        else:
            upper_op = '<='

    return [(lower_op, lower_version), (upper_op, upper_version)]


def _parse_tilde_caret(range_str: str) -> List[Tuple[str, Version]]:
    """Parse tilde (~) and caret (^) ranges."""
    range_str = range_str.strip()

    if not range_str:
        raise ValueError("Empty comparator")

    if range_str.startswith('~'):
        version_part = range_str[1:].strip()
        # Parse version
        try:
            version = parse(version_part)
        except ValueError:
            major, minor, patch, _, _ = _parse_partial_version(version_part)
            version = Version(major, minor, patch, [], None)

        if version.prerelease:
            # Tilde with prerelease: only exact match
            return [('>=', version), ('<=', version)]
        else:
            # ~X.Y.Z is >=X.Y.Z <(X+1).0.0
            # ~X.Y is >=X.Y.0 <(X+1).0.0
            # ~X is >=X.0.0 <(X+1).0.0
            upper_major = version.major
            if version.minor == 0 and version.patch == 0:
                # ~X or ~X.0
                upper_major = version.major + 1
                upper_minor = 0
                upper_patch = 0
            else:
                upper_major = version.major
                upper_minor = version.minor + 1
                upper_patch = 0
            upper_version = Version(upper_major, upper_minor, upper_patch, [], None)
            return [('>=', version), ('<', upper_version)]

    elif range_str.startswith('^'):
        version_part = range_str[1:].strip()
        # Parse version
        try:
            version = parse(version_part)
        except ValueError:
            major, minor, patch, _, _ = _parse_partial_version(version_part)
            version = Version(major, minor, patch, [], None)

        if version.prerelease:
            # Caret with prerelease: only same major.minor.patch with matching prerelease
            # ^0.0.3 is >=0.0.3 <0.0.4
            # ^0.0.0-alpha.1 is >=0.0.0-alpha.1 <0.0.0
            if version.major == 0 and version.minor == 0:
                upper_version = Version(0, 0, version.patch + 1, [], None)
                return [('>=', version), ('<', upper_version)]
            else:
                # Same major.minor.patch
                return [('>=', version), ('<=', version)]
        else:
            # Caret without prerelease
            if version.major == 0:
                if version.minor == 0:
                    # ^0.0.3 is >=0.0.3 <0.0.4
                    upper_version = Version(0, 0, version.patch + 1, [], None)
                    return [('>=', version), ('<', upper_version)]
                else:
                    # ^0.2.3 is >=0.2.3 <0.3.0
                    upper_version = Version(0, version.minor + 1, 0, [], None)
                    return [('>=', version), ('<', upper_version)]
            else:
                # ^1.2.3 is >=1.2.3 <2.0.0
                upper_version = Version(version.major + 1, 0, 0, [], None)
                return [('>=', version), ('<', upper_version)]

    else:
        return _parse_comparator(range_str)


def _satisfies_comparator(version: Version, op: str, target: Version, target_is_partial: bool = False, 
                         target_wildcard_minor: bool = False, target_wildcard_patch: bool = False) -> bool:
    """Check if version satisfies a comparator."""
    # Special case for '*' (any version)
    if op == '*':
        return True

    # Build metadata is ignored
    if op == '=':
        # Exact match, ignoring build metadata
        return version.major == target.major and version.minor == target.minor and version.patch == target.patch and version.prerelease == target.prerelease
    elif op == '>':
        # Must be greater than target
        # If target is prerelease and version is release, version is greater
        if target.prerelease and not version.prerelease:
            return True
        if not target.prerelease and version.prerelease:
            return False

        # Check if version is greater than target
        return version > target
    elif op == '>=':
        # Must be greater than or equal to target
        if target.prerelease and not version.prerelease:
            return True
        if not target.prerelease and version.prerelease:
            return False

        return version >= target
    elif op == '<':
        # Must be less than target
        # If version is prerelease and target is release, version might be less
        if not version.prerelease and target.prerelease:
            return False
        if version.prerelease and not target.prerelease:
            return True

        return version < target
    elif op == '<=':
        # Must be less than or equal to target
        if not version.prerelease and target.prerelease:
            return False
        if version.prerelease and not target.prerelease:
            return True

        return version <= target

    return False


def _is_partial_version_comparator(comparator: Tuple[str, Version]) -> bool:
    """Check if a comparator uses a partial version (wildcard)."""
    op, version = comparator
    # Check if the version is wildcard (not fully specified)
    if op == '*' or version.major == 0 and version.minor == 0 and version.patch == 0:
        return True

    return False


