def _parse_range_set(range_str: str) -> Tuple[List[List[Tuple[str, Version]]], List[List[Tuple[bool, bool, bool]]]]:
    """Parse a range string into a list of comparator sets and partial info."""
    # Split by ||
    sets = []
    partial_infos = []

    # Normalize spaces and split by ||
    range_str = range_str.strip()
    if not range_str:
        raise ValueError("Empty range")

    set_parts = range_str.split('||')

    for set_part in set_parts:
        set_part = set_part.strip()
        if not set_part:
            # Empty set part means all versions
            sets.append([('*', None)])
            partial_infos.append([(False, False, False)])
            continue

        # Split by whitespace
        comparators_str = set_part.split()
        if not comparators_str:
            # Empty comparator set
            sets.append([('*', None)])
            partial_infos.append([(False, False, False)])
            continue

        # Parse each comparator
        comparators = []
        partial_info = []

        for comp_str in comparators_str:
            if not comp_str.strip():
                continue

            # Try hyphen first
            if ' - ' in comp_str:
                hyphen_parts = _parse_hyphen_range(comp_str.strip())
                for op, version in hyphen_parts:
                    comparators.append((op, version))
                    # Check if partial version
                    wildcard_major = False
                    wildcard_minor = False
                    wildcard_patch = False
                    if version.major == 0 and version.minor == 0 and version.patch == 0:
                        # Check if it was originally a wildcard
                        # We'll handle this more carefully in the next step
                        wildcard_major = True
                        wildcard_minor = True
                        wildcard_patch = True
                    elif version.minor == 0 and version.patch == 0:
                        wildcard_minor = True
                        wildcard_patch = True
                    elif version.patch == 0:
                        wildcard_patch = True

                    partial_info.append((wildcard_major, wildcard_minor, wildcard_patch))
            else:
                # Try tilde or caret
                if comp_str.startswith('~') or comp_str.startswith('^'):
                    result = _parse_tilde_caret(comp_str)
                else:
                    result = _parse_comparator(comp_str)

                for op, version in result:
                    comparators.append((op, version))
                    # Check if partial version
                    wildcard_major = False
                    wildcard_minor = False
                    wildcard_patch = False
                    if version.major == 0 and version.minor == 0 and version.patch == 0:
                        wildcard_major = True
                        wildcard_minor = True
                        wildcard_patch = True
                    elif version.minor == 0 and version.patch == 0:
                        wildcard_minor = True
                        wildcard_patch = True
                    elif version.patch == 0:
                        wildcard_patch = True

                    partial_info.append((wildcard_major, wildcard_minor, wildcard_patch))

        if not comparators:
            # Empty set means all versions
            sets.append([('*', None)])
            partial_infos.append([(False, False, False)])
        else:
            sets.append(comparators)
            partial_infos.append(partial_info)

    return sets, partial_infos


def satisfies(version_str: str, rng: str) -> bool:
    """Check if a version satisfies a range."""
    try:
        version = parse(version_str)
    except ValueError:
        return False

    # Parse range
    try:
        sets, partial_infos = _parse_range_set(rng)
    except ValueError:
        return False

    # Check each set
    for i, comparators in enumerate(sets):
        partial_info = partial_infos[i] if i < len(partial_infos) else [(False, False, False)]
        if _satisfies_comparator_set(version, comparators, [partial_info]):
            return True

    return False


def max_satisfying(versions: List[str], rng: str) -> Optional[str]:
    """Return the highest version that satisfies the range, or None."""
    if not versions:
        return None

    # Parse versions and check satisfaction
    satisfying_versions = []

    for v in versions:
        try:
            if satisfies(v, rng):
                satisfying_versions.append(v)
        except ValueError:
            # Invalid version in the list - skip
            continue

    if not satisfying_versions:
        return None

    # Sort by SemVer precedence
    def compare_versions(v1, v2):
        v1_obj = parse(v1)
        v2_obj = parse(v2)
        if v1_obj < v2_obj:
            return -1
        elif v1_obj > v2_obj:
            return 1
        else:
            return 0

    # Sort in descending order
    satisfying_versions.sort(key=cmp_to_key(lambda a, b: -compare_versions(a, b)))

    return satisfying_versions[0]


