def split_command(line: str, env: dict[str, str]) -> list[str]:
    """
    Split a command line into words, performing shell-like word splitting
    and parameter expansion.
    """
    result = []
    i = 0
    n = len(line)

    # Stack to track context during parsing
    # Each element: (word_so_far, quote_char, needs_field_splitting)
    stack = []

    # Current state
    word = []
    quote = None  # None, "'", or '"'
    needs_split = False

    while i < n:
        c = line[i]

        # Backslash handling
        if c == '\\':
            if i + 1 < n and line[i + 1] == '\n':
                # Backslash-newline is removed entirely
                i += 2
                continue
            if quote == '"':
                # In double quotes, only \ escapes $, ", \, and newline
                if i + 1 < n and line[i + 1] in '$"\\':
                    word.append(line[i + 1])
                    i += 2
                    continue
                # Otherwise backslash is literal
            # Outside double quotes or in single quotes: backslash escapes next char
            if i + 1 < n:
                word.append(line[i + 1])
                i += 2
            else:
                raise ValueError("Trailing unescaped backslash")
            continue

        # Quote handling
        if c == "'":
            if quote is None:
                quote = "'"
            elif quote == "'":
                quote = None
            else:
                # Inside double quotes, single quote is literal
                word.append(c)
            i += 1
            continue

        if c == '"':
            if quote is None:
                quote = '"'
            elif quote == '"':
                quote = None
            else:
                # Inside single quotes, double quote is literal
                word.append(c)
            i += 1
            continue

        # Whitespace handling
        if c in ' \t\n':
            if quote is None:
                # Not in quotes: whitespace separates words
                if word or needs_split:
                    final_word = ''.join(word)
                    if needs_split:
                        # Field split on whitespace
                        for w in final_word.split():
                            if w:
                                result.append(w)
                    else:
                        result.append(final_word)
                    word = []
                    needs_split = False
                i += 1
            else:
                # Inside quotes: whitespace is literal
                word.append(c)
                i += 1
            continue

        # $ expansion (except in single quotes)
        if c == '$' and quote != "'":
            # Save current context
            stack.append((word, quote, needs_split))

            # Reset context for expansion
            word = []
            quote = None
            needs_split = True

            i += 1
            if i >= n:
                raise ValueError("Trailing $")

            if line[i] == '{':
                # ${...} expansion
                i += 1
                start = i

                # Find closing brace
                brace_count = 1
                while i < n and brace_count > 0:
                    if line[i] == '{':
                        brace_count += 1
                    elif line[i] == '}':
                        brace_count -= 1
                    i += 1

                if brace_count != 0:
                    raise ValueError("Unterminated ${")

                expansion_text = line[start:i-1]

                # Parse NAME:-default or NAME-default
                colon_idx = expansion_text.find(':')
                dash_idx = expansion_text.find('-')

                if colon_idx != -1 and (dash_idx == -1 or colon_idx < dash_idx):
                    # $NAME:-default
                    name = expansion_text[:colon_idx]
                    default_text = expansion_text[colon_idx+1:]
                elif dash_idx != -1:
                    # $NAME-default or $NAME:-default with dash first
                    name = expansion_text[:dash_idx]
                    default_text = expansion_text[dash_idx+1:]
                else:
                    # $NAME only
                    name = expansion_text
                    default_text = ""

                # Validate name
                if not name or not (name[0].isalpha() or name[0] == '_'):
                    raise ValueError(f"Invalid variable name: {name}")
                for ch in name[1:]:
                    if not (ch.isalnum() or ch == '_'):
                        raise ValueError(f"Invalid variable name: {name}")

                # Get value
                value = env.get(name, "")

                # Apply default logic
                if colon_idx != -1 and dash_idx != -1:
                    if colon_idx < dash_idx:
                        # $NAME:-default
                        if not value:  # unset or empty
                            value = expand_default(default_text, env)
                    else:
