                        if not value:
                            value = expand_default(default_text, env)
                elif colon_idx != -1:
                    # $NAME:-default
                    if not value:
                        value = expand_default(default_text, env)
                elif dash_idx != -1:
                    # $NAME-default
                    if not value:
                        value = expand_default(default_text, env)
                # else: no default

                word.append(value)
            else:
                # $NAME expansion (no braces)
                var_start = i
                while i < n and (line[i].isalnum() or line[i] == '_'):
                    i += 1

                var_name = line[var_start:i]

                # Validate name (at least one char)
                if not var_name:
                    raise ValueError("Empty variable name")

                # Get value
                value = env.get(var_name, "")
                word.append(value)

                # Back up i by 1 since we advanced past the variable name
                i -= 1

            # Restore previous context and merge
            prev_word, prev_quote, prev_needs_split = stack.pop()

            # Merge: append to previous word
            if word:
                prev_word.append(word[0])

            word = prev_word
            quote = prev_quote
            needs_split = prev_needs_split or needs_split
            continue

        # Regular character
        word.append(c)
        i += 1

    # Final cleanup
    if quote is not None:
        raise ValueError("Unterminated quote")

    # Process final word
    if word or needs_split:
        final_word = ''.join(word)
        if needs_split:
            for w in final_word.split():
                if w:
                    result.append(w)
        else:
            result.append(final_word)

