                if not name or not (name[0].isalpha() or name[0] == '_'):
                    raise ValueError(f"Invalid variable name: {name}")
                for ch in name[1:]:
                    if not (ch.isalnum() or ch == '_'):
                        raise ValueError(f"Invalid variable name: {name}")

                # Get value
                value = env.get(name, "")

                # Apply default logic
                if colon_idx != -1 and dash_idx != -1:
                    if colon_idx < dash_idx:
                        if not value:
                            value = expand_default(default_text, env)
                    else:
                        if not value:
                            value = expand_default(default_text, env)
                elif colon_idx != -1:
                    if not value:
                        value = expand_default(default_text, env)
                elif dash_idx != -1:
                    if not value:
                        value = expand_default(default_text, env)

                result.append(value)
            elif i + 1 < n and (text[i+1].isalnum() or text[i+1] == '_'):
                # $NAME
                j = i + 1
                while j < n and (text[j].isalnum() or text[j] == '_'):
                    j += 1

                var_name = text[i+1:j]
                if not var_name:
                    raise ValueError("Empty variable name")

                value = env.get(var_name, "")
                result.append(value)
                i = j
                continue
            else:
                # Just $, literal
                result.append(c)
                i += 1
                continue
        else:
            result.append(c)
            i += 1

    return ''.join(result)
